import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlsplit

source = Path('products/services/peppol-implementer-pilot/raw/openpeppol-provider-navigation.html')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '41db92d2709636a03d99d6b5c5143b76e668557992a16565ecee803b8c3fa015', digest

class DirectoryParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.row = None
        self.rows = []

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.row = {'text': [], 'hosts': set()}
        if tag == 'a' and self.row is not None:
            url = urlsplit(dict(attrs).get('href') or '')
            if url.scheme in ('http', 'https') and url.hostname:
                self.row['hosts'].add(url.hostname)

    def handle_data(self, data):
        if self.row is not None:
            self.row['text'].append(data)

    def handle_endtag(self, tag):
        if tag == 'tr' and self.row is not None:
            self.rows.append(self.row)
            self.row = None

parser = DirectoryParser()
parser.feed(raw.decode('utf-8'))
country = re.compile(r'\bCanad(?:a|ian)\b', re.IGNORECASE)
matches = []
for number, row in enumerate(parser.rows, 1):
    text = ' '.join(' '.join(row['text']).split())
    references = sorted({match.group() for match in country.finditer(text)})
    if references:
        matches.append({'table_row': number, 'country_references': references, 'linked_hosts': sorted(row['hosts'])})
result = {'source': 'https://peppol.org/members/peppol-certified-service-providers/', 'source_sha256': digest, 'table_rows_parsed': len(parser.rows), 'country_reference_rows': len(matches), 'rows': matches, 'scope': 'Explicit Canada or Canadian text in HTML table rows only. Linked hosts are navigation hints. An empty result does not rule out providers in other markup or providers that omit country references. Rows do not establish purchasing intent, eligibility, or permission to contact.'}
output = Path('products/services/peppol-implementer-pilot/director-country-row-navigation.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
